INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Drucker Funktion, Einsatz, Varianten > Laserdrucker
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Laserdrucker unabhängig von der Toner-Kompatibilität ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Drucker benötigen spezifischen Toner"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Druck"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines Laserdruckers immer die Druckvolumen-Anforderungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Volumen beeinflusst Eignung und Kosten"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Druckgeschwindigkeit eines Laserdruckers für alle Anwendungen irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit wichtig bei hohem Volumen"}, {"text": "Ja", "correct": false, "because": "Beeinflusst Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Laserdrucker ohne Rücksicht auf die Netzwerkfähigkeit ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Netzwerk wichtig für Büroumgebungen"}, {"text": "Ja", "correct": false, "because": "Anwendung bestimmt Anforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Farb-Laserdrucker immer teurer als Monochrom-Modelle?', 2, '[{"text": "Ja", "correct": true, "because": "Farbdruck erhöht Kosten"}, {"text": "Nein", "correct": false, "because": "Preisunterschied ist üblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines Laserdruckers am wichtigsten?', 3, '[{"text": "Druckanforderungen", "correct": true, "because": "Bestimmen Geschwindigkeit und Typ"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird für moderne Laserdrucker am häufigsten verwendet?', 2, '[{"text": "USB", "correct": true, "because": "Universeller Standard"}, {"text": "Parallelport", "correct": false, "because": "Veraltet"}, {"text": "Serial", "correct": false, "because": "Weniger gebräuchlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit misst die Druckgeschwindigkeit eines Laserdruckers?', 2, '[{"text": "PPM", "correct": true, "because": "Pages per Minute gibt Tempo an"}, {"text": "DPI", "correct": false, "because": "Auflösung, nicht Geschwindigkeit"}, {"text": "Watt", "correct": false, "because": "Leistungsaufnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verbrauchsmaterial ist für Laserdrucker essenziell?', 3, '[{"text": "Toner", "correct": true, "because": "Staubförmige Farbe für Laserdruck"}, {"text": "Tintenpatronen", "correct": false, "because": "Für Tintenstrahldrucker"}, {"text": "Farbbänder", "correct": false, "because": "Für Impactdrucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Laserdruckern gegenüber Tintenstrahldruckern?', 2, '[{"text": "Höhere Druckgeschwindigkeit", "correct": true, "because": "Schneller bei großen Volumen"}, {"text": "Geringere Anschaffungskosten", "correct": false, "because": "Oft teurer"}, {"text": "Kleinere Größe", "correct": false, "because": "Nicht zwangsläufig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines Laserdruckers?', 4, '[{"text": "Druckvolumen", "correct": true, "because": "Bestimmt Kapazität"}, {"text": "Druckauflösung", "correct": true, "because": "Beeinflusst Qualität"}, {"text": "Netzwerkfähigkeit", "correct": true, "because": "Für Büroumgebungen"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Laserdrucker?', 3, '[{"text": "Hohe Druckgeschwindigkeit", "correct": true, "because": "Effizient bei Volumen"}, {"text": "Gute Textqualität", "correct": true, "because": "Scharfe Schrift"}, {"text": "Langlebiger Druck", "correct": true, "because": "Toner verblasst nicht schnell"}, {"text": "Geringere Wartung", "correct": false, "because": "Tonerwechsel nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl eines Laserdruckers auftreten?', 3, '[{"text": "Hohe Anschaffungskosten", "correct": true, "because": "Teurer als Tintenstrahl"}, {"text": "Unzureichende Auflösung", "correct": true, "because": "Für Grafiken wichtig"}, {"text": "Begrenztes Druckvolumen", "correct": true, "because": "Modellabhängig"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen können Laserdrucker unterstützen?', 4, '[{"text": "Duplexdruck", "correct": true, "because": "Beidseitiges Drucken"}, {"text": "Netzwerkdruck", "correct": true, "because": "Für mehrere Nutzer"}, {"text": "Farbdruck", "correct": true, "because": "Bei Farbmodellen"}, {"text": "3D-Druck", "correct": false, "because": "Andere Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von Laserdruckern?', 3, '[{"text": "Bürodokumente", "correct": true, "because": "Schnell und klar"}, {"text": "Rechnungen", "correct": true, "because": "Hohe Textqualität"}, {"text": "Massendruck", "correct": true, "because": "Effizient bei Volumen"}, {"text": "Fotodruck", "correct": false, "because": "Tintenstrahl besser"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Laserdrucker verwenden Toner statt Tinte. b) Sie sind für Fotodruck besser geeignet als Tintenstrahldrucker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Toner ja, Fotodruck nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PPM misst die Druckgeschwindigkeit bei Laserdruckern. b) Laserdrucker sind immer langsamer als Tintenstrahldrucker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "PPM ja, Laser oft schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Laserdrucker bieten hohe Textqualität. b) Netzwerkfähigkeit ist bei allen Modellen Standard.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Textqualität ja, Netzwerk optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Farb-Laserdrucker sind teurer als Monochrom-Modelle. b) Laserdrucker sind ungeeignet für Büroumgebungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Farbdruck ja, Büro geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Laserdrucker sind effizient bei hohen Druckvolumen. b) Toner ist günstiger als Tintenpatronen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Volumen ja, Toner oft teurer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

